fn cardsFrom(html, base) {
  let out = []
  let hrefs = matchAll(html, '<a href="([^"]+)"[^>]*itemprop="url"', 1)
  let names = matchAll(html, '<h3 itemprop="name">([^<]+)</h3>', 1)
  let covers = matchAll(html, 'src="([^"]+)"[^>]*wp-post-image', 1)
  let authors = matchAll(html, 'chuyen-muc"[^>]*>[\s\S]*?<a>([^<]+)</a>', 1)
  let n = len(hrefs)
  if len(names) < n {
    n = len(names)
  }
  for h, i in hrefs {
    if i < n {
      let u = absUrl(h, base)
      if contains(u, '/novel') {
        let c = ''
        if i < len(covers) {
          c = absUrl(covers[i], base)
        }
        push(out, {name: names[i], bookUrl: u, coverUrl: c, author: i < len(authors) ? authors[i] : ''})
      }
    }
  }
  return out
}

fn chaptersFrom(html, base) {
  let out = []
  let block = match(html, 'id="list-chapter"([\s\S]*?)id="pagination"', 1)
  if block == '' {
    return []
  }
  let hrefs = matchAll(block, '<a href="([^"]+)"', 1)
  let names = matchAll(block, 'chapter-text">([^<]*)</span>', 1)
  for h, i in hrefs {
    if i < len(names) {
      let u = absUrl(h, base)
      if u != '' {
        push(out, {name: names[i], url: u})
      }
    }
  }
  return out
}

fn imagesFrom(html, base) {
  let out = []
  let a = matchAll(html, "data-original='([^']+)'", 1)
  if len(a) == 0 {
    a = matchAll(html, 'data-original="([^"]+)"', 1)
  }
  for u in a {
    let x = absUrl(u, base)
    if x != '' {
      push(out, x)
    }
  }
  return out
}
